#include <stdio.h>
// 独立请求：每设备一对线(BR_i 请求 / BG_i 授权)，中央仲裁器用优先级编码器选最高优先级
// 优先级顺序可任意编程：这里设 设备2 > 设备0 > 设备3 > 设备1
int prio[4] = {2, 0, 3, 1};          // 从高到低
int req[8] = {1, 6, 8, 2, 13, 0, 4, 6};
int main() {
    printf("独立请求仲裁 (优先级 设备2 > 0 > 3 > 1)\n");
    printf("cycle   请求   授权设备\n");
    for (int c = 0; c < 8; c++) {
        int r = req[c];
        int g = -1;
        for (int k = 0; k < 4; k++) {
            int i = prio[k];
            if (r & (1 << i)) { g = i; break; }
        }
        printf("  %d      %2d       %d\n", c, r, g);
    }
    return 0;
}
